/**
 * Template timeline: web/fixtures/timeline.seed.json (generated by web/scripts/data/build_timeline.py,
 * story in docs/plan/visits-script.md). This module validates it once and maps it into store rows.
 *
 * Every call to buildSeedTables() returns fresh objects, so each session gets its own deep copy.
 * Rows that have no id in the seed get deterministic ids (bp-d3-evening, dose-d15-med-amlodipine-morning,
 * note-d37-1, item-R4) so tests and later modules can refer to them across resets.
 */
import { z } from "zod";
import seedJson from "@/fixtures/timeline.seed.json";
import { storyDate } from "./clock";
import type {
  BpReadingRow,
  DoseLogRow,
  FamilyGrantItems,
  FamilyGrantRow,
  MedicationRow,
  NoteRow,
  ProfileFactRow,
  QuestionRow,
  ReminderClipRow,
  TemplateId,
  UtteranceRow,
  VisitItemRow,
  VisitRow,
} from "@/lib/store/types";

// ---------------------------------------------------------------- schema (only what the mapper reads)

const slot = z.enum(["morning", "midday", "evening", "night"]);
const utteranceRole = z.enum(["doctor", "dispenser", "pharmacist", "patient", "family", "unknown"]);
const grantItems = z.object({
  dose_summary: z.boolean(),
  bp_summary: z.boolean(),
  questions_count: z.boolean(),
  no_reply_alert: z.boolean(),
  visit_transcripts: z.boolean(),
  notes: z.boolean(),
});

const seedSchema = z.looseObject({
  meta: z.looseObject({
    d0: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    judge_landing_day: z.number().int(),
    story: z.string().optional(),
    note: z.string().optional(),
  }),
  persona: z.looseObject({
    id: z.string(),
    display_name: z.string(),
    chinese_name: z.string().optional(),
    age: z.number().optional(),
    home: z.string().optional(),
    languages: z.array(z.string()).optional(),
    ui_language: z.string().optional(),
    large_text: z.boolean().optional(),
    routine: z
      .array(
        z.looseObject({
          label: z.string(),
          label_zh: z.string().optional(),
          days: z.union([z.literal("daily"), z.array(z.string())]),
          time: z.string(),
        }),
      )
      .optional(),
    healthier_sg_clinic: z.string().optional(),
  }),
  family: z.array(
    z.looseObject({
      id: z.string(),
      display_name: z.string(),
      relation: z.string(),
      age: z.number().optional(),
    }),
  ),
  family_grants: z.record(z.string(), grantItems),
  visits: z.array(
    z.looseObject({
      id: z.string(),
      day: z.number().int(),
      date: z.string().optional(),
      kind: z.string(),
      place: z.string(),
      script_section: z.string().optional(),
      audio_fixture: z.string().optional(),
    }),
  ),
  required_doctor_lines: z.array(
    z.looseObject({
      id: z.enum(["R1", "R2", "R3", "R4"]),
      visit: z.string(),
      speaker: utteranceRole,
      text: z.string(),
      kind: z.enum(["target", "threshold", "purpose", "instruction"]),
      slots: z.record(z.string(), z.unknown()).optional(),
    }),
  ),
  medications: z.array(
    z.looseObject({
      id: z.string(),
      drug_id: z.string().nullable(),
      origin: z.enum(["prescription", "self_bought", "relative", "supplement"]),
      prescribed_visit: z.string().optional(),
      start_day: z.number().int().optional(),
      label: z
        .looseObject({
          text: z.string(),
          drug: z.string().optional(),
          strength: z.string().optional(),
          directions: z.string().optional(),
          dispensed: z.string().optional(),
          clinic: z.string().optional(),
          photo_fixture: z.string().optional(),
        })
        .nullable(),
      status: z.enum(["awaiting_label", "label_confirmed", "pharmacist_checked", "unverified", "unidentified"]),
      note: z.string().optional(),
      pharmacist_answer: z.object({ visit: z.string(), text: z.string() }).optional(),
    }),
  ),
  bp_readings: z.array(
    z.looseObject({
      day: z.number().int(),
      slot,
      systolic: z.number().optional(),
      diastolic: z.number().optional(),
      state: z.enum(["recorded", "unconfirmed"]).optional(),
      note: z.string().optional(),
    }),
  ),
  dose_log: z.array(
    z.looseObject({
      day: z.number().int(),
      med: z.string(),
      slot,
      state: z.enum(["taken", "missed", "unconfirmed"]),
      reason: z.string().optional(),
      reason_text_zh: z.string().optional(),
    }),
  ),
  notes: z.array(
    z.looseObject({
      day: z.number().int(),
      text_zh: z.string().optional(),
      text: z.string().optional(),
      source: z.enum(["typed", "voice_note"]),
      app_reply: z.string().optional(),
    }),
  ),
  questions: z.array(
    z.looseObject({
      id: z.string(),
      for: z.enum(["doctor", "pharmacist"]),
      origin: z.enum(["own", "before_you_go", "refused_question", "pattern", "unidentified_medicine", "understanding_check"]),
      text_zh: z.string().optional(),
      text: z.string().optional(),
      status: z.enum(["open", "answered", "skipped"]),
      asked_at_visit: z.string().optional(),
      created_day: z.number().int().optional(),
      evidence: z.string().optional(),
      answer: z.object({ visit: z.string(), speaker: utteranceRole, text: z.string() }).optional(),
    }),
  ),
  reminder_clips: z.array(
    z.looseObject({
      id: z.string(),
      by: z.string(),
      text_zh: z.string().optional(),
      text: z.string().optional(),
      audio_fixture: z.string().optional(),
      plays_at: z.string(),
    }),
  ),
});

export type SeedTimeline = z.infer<typeof seedSchema>;
export type Persona = SeedTimeline["persona"];
export type FamilyMember = SeedTimeline["family"][number];

let parsed: SeedTimeline | null = null;

/** The validated template timeline (shared, read-only: never mutate it; buildSeedTables copies). */
export function loadTemplate(template: TemplateId = "mr-tan"): Readonly<SeedTimeline> {
  if (template !== "mr-tan") throw new Error(`Unknown template: ${template}`);
  if (!parsed) {
    const result = seedSchema.safeParse(seedJson);
    if (!result.success) {
      throw new Error(`web/fixtures/timeline.seed.json does not match the expected shape: ${result.error.message}`);
    }
    parsed = result.data;
  }
  return parsed;
}

export interface TemplateDefaults {
  d0: string;
  story_day: number;
  story_time: string | null;
}

export function templateDefaults(template: TemplateId = "mr-tan"): TemplateDefaults {
  const seed = loadTemplate(template);
  return { d0: seed.meta.d0, story_day: seed.meta.judge_landing_day, story_time: null };
}

/** Persona and family for page headers (copies). */
export function templateCast(template: TemplateId = "mr-tan"): { persona: Persona; family: FamilyMember[] } {
  const seed = loadTemplate(template);
  return { persona: structuredClone(seed.persona), family: structuredClone(seed.family) };
}

// ---------------------------------------------------------------- mapper

export interface SeedTables {
  visits: VisitRow[];
  visit_items: VisitItemRow[];
  medications: MedicationRow[];
  dose_logs: DoseLogRow[];
  bp_readings: BpReadingRow[];
  notes: NoteRow[];
  questions: QuestionRow[];
  family_grants: FamilyGrantRow[];
  reminder_clips: ReminderClipRow[];
  // C2 track C: only an account's laid-out space carries these (the example's transcripts and profile facts,
  // lib/story/example.ts); the demo's seed has neither
  utterances?: UtteranceRow[];
  profile_facts?: ProfileFactRow[];
}

function hasHan(text: string): boolean {
  return /\p{Script=Han}/u.test(text);
}

/** Fresh store rows for one session. */
export function buildSeedTables(sessionId: string, now: string, template: TemplateId = "mr-tan"): SeedTables {
  const seed = loadTemplate(template);
  const d0 = seed.meta.d0;
  const visitDay = new Map(seed.visits.map((v) => [v.id, v.day]));
  const base = { session_id: sessionId, created_at: now };

  const visits: VisitRow[] = seed.visits.map((v) => ({
    ...base,
    id: v.id,
    kind: v.kind,
    place: v.place,
    day: v.day,
    date: v.date ?? storyDate(d0, v.day),
    consent_utterance_id: null,
    status: "confirmed",
    audio_path: null,
    script_section: v.script_section ?? null,
    audio_fixture: v.audio_fixture ?? null,
  }));

  const visit_items: VisitItemRow[] = seed.required_doctor_lines.map((r) => ({
    ...base,
    id: `item-${r.id}`,
    visit_id: r.visit,
    type: r.kind,
    text: r.text,
    utterance_ids: [],
    slots: structuredClone(r.slots ?? {}),
    confirmed_by: null,
    required_line: r.id,
    speaker: r.speaker,
  }));

  const medications: MedicationRow[] = seed.medications.map((m) => ({
    ...base,
    id: m.id,
    drug_id: m.drug_id,
    origin: m.origin,
    label: m.label ? structuredClone(m.label) : null,
    status: m.status,
    start_day: m.start_day ?? null,
    prescribed_visit_id: m.prescribed_visit ?? null,
    note: m.note ?? null,
    pharmacist_answer: m.pharmacist_answer
      ? { visit_id: m.pharmacist_answer.visit, text: m.pharmacist_answer.text }
      : null,
  }));

  const usedIds = new Set<string>();
  const uniqueId = (wanted: string): string => {
    let id = wanted;
    for (let n = 2; usedIds.has(id); n++) id = `${wanted}-${n}`;
    usedIds.add(id);
    return id;
  };

  const dose_logs: DoseLogRow[] = seed.dose_log.map((d) => ({
    ...base,
    id: uniqueId(`dose-d${d.day}-${d.med}-${d.slot}`),
    medication_id: d.med,
    day: d.day,
    slot: d.slot,
    state: d.state,
    reason: d.reason ?? null,
    reason_text: d.reason_text_zh ?? null,
  }));

  const bp_readings: BpReadingRow[] = seed.bp_readings.map((b) => ({
    ...base,
    id: uniqueId(`bp-d${b.day}-${b.slot}`),
    day: b.day,
    slot: b.slot,
    systolic: b.systolic ?? null,
    diastolic: b.diastolic ?? null,
    state: b.state ?? (b.systolic == null ? "unconfirmed" : "recorded"),
    note: b.note ?? null,
  }));

  const notes: NoteRow[] = seed.notes.map((n, i) => {
    const text = n.text_zh ?? n.text ?? "";
    return {
      ...base,
      id: uniqueId(`note-d${n.day}-${i + 1}`),
      day: n.day,
      text,
      source: n.source,
      lang: n.text_zh ? "zh-Hans" : hasHan(text) ? "zh-Hans" : "en",
      app_reply: n.app_reply ?? null,
    };
  });

  const questions: QuestionRow[] = seed.questions.map((q) => {
    const text = q.text_zh ?? q.text ?? "";
    return {
      ...base,
      id: q.id,
      for: q.for,
      origin: q.origin,
      text,
      lang: q.text_zh ? "zh-Hans" : hasHan(text) ? "zh-Hans" : "en",
      status: q.status,
      answer_text: q.answer?.text ?? null,
      answer_utterance_id: null, // linked by M2 once utterances exist
      answer_visit_id: q.answer?.visit ?? null,
      answer_speaker: q.answer?.speaker ?? null,
      asked_at_visit_id: q.asked_at_visit ?? null,
      created_day: q.created_day ?? (q.asked_at_visit ? (visitDay.get(q.asked_at_visit) ?? null) : null),
      evidence: q.evidence ?? null,
    };
  });

  const family_grants: FamilyGrantRow[] = Object.entries(seed.family_grants).map(([member, items]) => ({
    ...base,
    member,
    items: { ...(items as FamilyGrantItems) },
    updated_at: now,
  }));

  const reminder_clips: ReminderClipRow[] = seed.reminder_clips.map((c) => {
    const text = c.text_zh ?? c.text ?? null;
    return {
      ...base,
      id: c.id,
      by: c.by,
      audio_path: c.audio_fixture ?? null,
      plays_at: c.plays_at,
      text,
      lang: c.text_zh ? "zh-Hans" : text && hasHan(text) ? "zh-Hans" : text ? "en" : null,
    };
  });

  return { visits, visit_items, medications, dose_logs, bp_readings, notes, questions, family_grants, reminder_clips };
}
